#### REQ-LENS-012-002: S3 Audit Log Storage (7-Year Retention)

**Status**: Mandatory (Phase 2)
**Rationale**: HIPAA requires 7-year retention for PHI access logs

**Storage Configuration**:
- S3 bucket: `eaas-lenses-audit-logs-{account-id}`
- Region: us-east-1
- Encryption: AWS KMS (key: `eaas-audit-logs`)
- Versioning: Enabled (tamper-proofing)
- Object Lock: COMPLIANCE mode (prevent deletion)
- Lifecycle policy: Delete after 7 years
- Access logging: Enabled (track who accessed audit logs)

**Implementation**:
```hcl
# Complete S3 Audit Log Storage Configuration with 7-Year Retention
# Terraform configuration with Object Lock COMPLIANCE mode

# Data source for account ID
data "aws_caller_identity" "current" {}

# KMS key for audit log encryption
resource "aws_kms_key" "audit_logs" {
  description             = "KMS key for Lenses.io audit log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "eaas-audit-logs"
    Purpose     = "Audit Log Encryption"
    Compliance  = "HIPAA,SOC2"
    Environment = "production"
  }
}

resource "aws_kms_alias" "audit_logs" {
  name          = "alias/eaas-audit-logs"
  target_key_id = aws_kms_key.audit_logs.key_id
}

# S3 bucket for audit logs with Object Lock
resource "aws_s3_bucket" "audit_logs" {
  bucket = "eaas-lenses-audit-logs-${data.aws_caller_identity.current.account_id}"

  tags = {
    Name        = "Lenses.io Audit Logs"
    Purpose     = "Audit Log Storage"
    Compliance  = "HIPAA,SOC2"
    Retention   = "7 years"
    Environment = "production"
  }
}

# Enable versioning (required for Object Lock)
resource "aws_s3_bucket_versioning" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Enable Object Lock in COMPLIANCE mode
resource "aws_s3_bucket_object_lock_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    default_retention {
      mode  = "COMPLIANCE"  # Cannot be deleted until retention expires
      years = 7             # 7-year retention for HIPAA
    }
  }
}

# Server-side encryption with KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.audit_logs.arn
    }
    bucket_key_enabled = true
  }
}

# Block public access
resource "aws_s3_bucket_public_access_block" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Lifecycle policy
resource "aws_s3_bucket_lifecycle_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    id     = "delete-after-7-years"
    status = "Enabled"

    expiration {
      days = 2557  # 7 years (365 * 7) + 2 days
    }

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

# Access logging bucket
resource "aws_s3_bucket" "audit_logs_access" {
  bucket = "eaas-lenses-audit-logs-access-${data.aws_caller_identity.current.account_id}"

  tags = {
    Name    = "Audit Logs Access Logs"
    Purpose = "Track audit log access"
  }
}

resource "aws_s3_bucket_logging" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  target_bucket = aws_s3_bucket.audit_logs_access.id
  target_prefix = "access-logs/"
}

# Bucket policy
resource "aws_s3_bucket_policy" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLensesWrite"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.lenses_audit_writer.arn
        }
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Resource = "${aws_s3_bucket.audit_logs.arn}/*"
      },
      {
        Sid    = "DenyUnencryptedUploads"
        Effect = "Deny"
        Principal = "*"
        Action = "s3:PutObject"
        Resource = "${aws_s3_bucket.audit_logs.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      }
    ]
  })
}

# IAM role for Lenses audit writer
resource "aws_iam_role" "lenses_audit_writer" {
  name = "LensesAuditLogWriter"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lenses_audit_writer" {
  name = "AuditLogWritePolicy"
  role = aws_iam_role.lenses_audit_writer.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Resource = "${aws_s3_bucket.audit_logs.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.audit_logs.arn
      }
    ]
  })
}
```
